import ladybug, tempfile, random
from oxide.storage.fts import fts_location
random.seed(1)
words = [f"w{i}" for i in range(60)]
def doc(): return " ".join(random.choice(words) for _ in range(random.randint(1, 12)))
docs = {f"k{i}": doc() for i in range(400)}
def mk(path, rows):
    db = ladybug.Database(path); c = ladybug.Connection(db)
    c.execute("CREATE NODE TABLE E(key STRING PRIMARY KEY, terms STRING)")
    for k, t in rows.items(): c.execute("CREATE (:E {key:$k, terms:$t})", {"k": k, "t": t})
    c.execute(f"LOAD EXTENSION '{fts_location()}'")
    c.execute("CALL CREATE_FTS_INDEX('E','lex',['terms'], stemmer := 'porter')")
    return db, c
def q(c, t): return sorted(c.execute(f"CALL QUERY_FTS_INDEX('E','lex','{t}', top := 1000) RETURN node.key, score").get_all())
with tempfile.TemporaryDirectory(dir="/tmp/cb") as d:
    db1, c1 = mk(d + "/a.lbug", docs)
    final = dict(docs)
    for k in random.sample(sorted(docs), 40):
        c1.execute("MATCH (e:E {key:$k}) DELETE e", {"k": k}); del final[k]
    for i in range(400, 450):
        t = doc(); final[f"k{i}"] = t; c1.execute("CREATE (:E {key:$k, terms:$t})", {"k": f"k{i}", "t": t})
    db2, c2 = mk(d + "/b.lbug", final)
    bad = 0
    for qq in ["w1", "w2 w3", "w10 w20 w30", "w59", "w0 w5"]:
        a, b = q(c1, qq), q(c2, qq)
        if a != b: bad += 1; print("DIFF", qq, len(a), len(b), [(x, y) for x, y in zip(a, b) if x != y][:3])
    print("bad", bad)
EOF

